<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Tree Peony Pavilion Poster</title>
<style>
    @import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;700&display=swap');

    body {
        margin: 0;
        padding: 20px;
        background-color: #222;
        display: flex;
        justify-content: center;
        align-items: center;
        min-height: 100vh;
    }

    .poster {
        width: 800px;
        height: 1150px;
        background-color: #f4f1ea;
        position: relative;
        font-family: 'Noto Serif SC', serif;
        color: #111;
        box-shadow: 0 0 20px rgba(0,0,0,0.5);
        overflow: hidden;
        box-sizing: border-box;
    }

    .red-dot {
        display: inline-block;
        width: 8px;
        height: 8px;
        background-color: #c82829;
        border-radius: 50%;
        margin-bottom: 8px;
    }

    .red-dot-inline {
        display: inline-block;
        width: 8px;
        height: 8px;
        background-color: #c82829;
        border-radius: 50%;
        margin-right: 5px;
        vertical-align: middle;
    }

    /* Top Right Logo */
    .top-right {
        position: absolute;
        top: 40px;
        right: 40px;
        font-family: cursive, 'Noto Serif SC';
        font-size: 28px;
        font-weight: bold;
        letter-spacing: 2px;
    }

    /* Seal */
    .seal {
        position: absolute;
        top: 50px;
        left: 280px;
        width: 46px;
        height: 46px;
        border: 2px solid #c82829;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        color: #c82829;
        font-size: 22px;
        font-weight: bold;
        box-sizing: border-box;
    }
    .seal-inner {
        width: 36px;
        height: 36px;
        border: 1px dashed #c82829;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    /* Left Vertical Text */
    .left-vertical {
        position: absolute;
        top: 250px;
        left: 50px;
        writing-mode: vertical-rl;
        text-orientation: mixed;
    }
    .left-vertical .eng {
        font-family: Arial, sans-serif;
        font-size: 13px;
        letter-spacing: 1px;
        margin-bottom: 30px;
    }
    .left-vertical .chi {
        font-size: 16px;
        letter-spacing: 4px;
    }

    /* Main Title */
    .title-area {
        position: absolute;
        top: 160px;
        left: 280px;
    }
    .title-eng {
        font-family: 'Noto Serif SC', serif;
        font-size: 26px;
        line-height: 1.3;
        margin-bottom: 15px;
    }
    .title-chi {
        font-size: 110px;
        letter-spacing: 20px;
        margin-bottom: 10px;
        line-height: 1;
    }
    .title-sub {
        display: flex;
        align-items: center;
        font-size: 22px;
        letter-spacing: 2px;
    }
    .title-sub .slash {
        color: #c82829;
        margin: 0 15px;
        font-size: 24px;
        font-weight: bold;
    }
    .title-sub .eng-sub {
        font-family: Arial, sans-serif;
        font-size: 12px;
        margin-right: 15px;
        text-transform: uppercase;
        letter-spacing: 1px;
    }
    .title-kunqu {
        font-family: Arial, sans-serif;
        font-size: 12px;
        text-transform: uppercase;
        letter-spacing: 2px;
        margin-top: 5px;
    }
    .main-red-dot {
        position: absolute;
        top: 180px;
        left: 530px;
        width: 12px;
        height: 12px;
        background-color: #c82829;
        border-radius: 50%;
    }

    /* Starring */
    .starring-area {
        position: absolute;
        top: 480px;
        left: 280px;
        display: flex;
    }
    .v-label {
        writing-mode: vertical-rl;
        font-size: 12px;
        letter-spacing: 2px;
        margin-right: 20px;
        display: flex;
        align-items: center;
        color: #333;
    }
    .starring-content {
        display: flex;
        flex-direction: column;
    }
    .starring-eng {
        font-family: Arial, sans-serif;
        font-size: 10px;
        line-height: 1.6;
        margin-bottom: 25px;
        text-transform: uppercase;
        color: #444;
    }
    .starring-chi {
        writing-mode: vertical-rl;
        height: 160px;
        font-size: 16px;
        line-height: 2.5;
        letter-spacing: 3px;
    }
    .starring-chi p {
        margin: 0;
    }

    /* Organizers */
    .organizers-area {
        position: absolute;
        top: 250px;
        right: 50px;
        writing-mode: vertical-rl;
        height: 450px;
        font-size: 12px;
        line-height: 2.5;
        letter-spacing: 1px;
    }
    .organizers-area p {
        margin: 0;
        margin-left: 15px;
    }

    /* Bottom Columns */
    .bottom-cols {
        position: absolute;
        bottom: 120px;
        left: 50px;
        right: 50px;
        display: flex;
        justify-content: space-between;
    }
    .col {
        display: flex;
        width: 30%;
    }
    .col-content {
        display: flex;
        flex-direction: column;
    }

    /* Actors */
    .actors-list {
        writing-mode: vertical-rl;
        height: 180px;
        font-size: 12px;
        line-height: 2.2;
        letter-spacing: 1px;
    }
    .actors-list p {
        margin: 0;
    }

    /* Time */
    .time-eng {
        font-family: Arial, sans-serif;
        font-size: 14px;
        line-height: 1.5;
        margin-bottom: 20px;
    }
    .time-chi {
        writing-mode: vertical-rl;
        height: 100px;
        font-size: 24px;
        letter-spacing: 5px;
        line-height: 1.8;
        margin-bottom: 20px;
    }
    .time-chi p {
        margin: 0;
    }
    .time-bot {
        font-family: Arial, sans-serif;
        font-size: 14px;
    }

    /* Location */
    .loc-eng {
        font-family: Arial, sans-serif;
        font-size: 11px;
        line-height: 1.4;
        margin-bottom: 20px;
    }
    .loc-chi {
        writing-mode: vertical-rl;
        height: 140px;
    }
    .loc-chi-name {
        font-size: 24px;
        letter-spacing: 4px;
        margin-right: 15px;
    }
    .loc-chi-addr {
        font-size: 12px;
        line-height: 1.8;
        letter-spacing: 1px;
    }

    /* Sponsors */
    .sponsors-area {
        position: absolute;
        bottom: 30px;
        left: 50px;
        right: 50px;
        display: flex;
        align-items: center;
        justify-content: center;
    }
    .sponsors-label {
        font-size: 12px;
        margin-right: 20px;
        display: flex;
        align-items: center;
    }
    .sponsor-logos {
        display: flex;
        gap: 15px;
    }
    .placeholder {
        height: 30px;
        padding: 0 15px;
        border: 1px solid #ccc;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 10px;
        color: #666;
        background: #fff;
    }
</style>
</head>
<body>

<div class="poster">
    <div class="top-right">春风上巳天</div>

    <div class="seal">
        <div class="seal-inner">昆</div>
    </div>

    <div class="left-vertical">
        <div class="eng">Upper And<br>Lower Chengdu Station</div>
        <div class="chi">上下本·成都站</div>
    </div>

    <div class="main-red-dot"></div>
    <div class="title-area">
        <div class="title-eng">Tree peony<br>Pavilion</div>
        <div class="title-chi">牡丹亭</div>
        <div class="title-sub">
            <span>昆曲</span>
            <span class="slash">/</span>
            <span class="eng-sub">Essence of</span>
            <span>精华版</span>
        </div>
        <div class="title-kunqu">Kunqu</div>
    </div>

    <div class="starring-area">
        <div class="v-label"><span class="red-dot"></span>领衔主演 : Starring</div>
        <div class="starring-content">
            <div class="starring-eng">
                KONG AIPING as Du Liniang and<br>
                SHI XIAOMEI as Liu Mengmei (top)<br>
